scope:
Replay identical separately compiled GELU controls on the same actual BF16 inputs.

Operator attribution only. Does not change Flare, its oracle, or any budget;
toolchain results do not by themselves identify a prebuilt Torch wheel's cubin.

configuration.CUDA_source:
#include <cuda_bf16.h>
#include <cmath>
// Same BF16 -> FP32 arithmetic order and constants as the fixed Torch sources.
extern "C" __global__ void gelu_control(const __nv_bfloat16* x, __nv_bfloat16* y,
                                       float* erf_values, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    float v = __bfloat162float(x[i]);
    constexpr float kAlpha = 0.707106781186547524400844362104849039;
    constexpr float kBeta = 0.5;
    constexpr float kOne = 1.0;
    float e = erff(v * kAlpha);
    erf_values[i] = e;
    y[i] = __float2bfloat16_rn(v * kBeta * (kOne + e));
}
